// 格式化微信推送参数
const message = msg.payload || '';
const channel = msg.channel || 'wechat/user_id';

if (!message) {
    node.warn('[微信推送] 消息内容为空，跳过');
    return null;
}

msg.payload = {
    channel: channel,
    message: String(message)
};

node.warn('[微信推送] 发送到 ' + channel + ': ' + String(message).substring(0, 30));
return msg;

const ROOM_MAP = {
  "书房": "xiaomi_x08a_1648",
  "卧室": "xiaomi_l06a_2dee",
  "主卧室浴室": "xiaomi_s12_10ca",
  "卫生间": "xiaomi_s12_b693",
  "主卧室": "xiaomi_l17a_60b3",
  "客厅左": "xiaomi_lx06_a137",
  "客厅右": "xiaomi_lx06_7709",
  "房间": "xiaomi_l06a_42e5"
};
const room = msg.room || (msg.payload && msg.payload.room);
const q = msg.question || (msg.payload && msg.payload.question);
const core = ROOM_MAP[room];
if (!core) { node.error("未知房间: " + room); return null; }
msg.conv = "sensor." + core + "_conversation";
msg.wake = "button." + core + "_wake_up";
msg.pt   = "text." + core + "_play_text";
msg.question = (q || "需要我帮你做什么？").toString();
msg.wakeTs = Date.now();
return msg;

const ts = msg.wakeTs || 0;
const ent = msg.data || {};
const lc = ent.last_changed ? new Date(ent.last_changed).getTime() : 0;
const ans = (msg.payload || "").toString().trim();
msg.answer = ans;
msg.need = ans.includes("需要") && lc > ts;
return msg;

const title = (typeof msg.title === 'string' && msg.title.length) ? msg.title : 'AutoFlow';
const body  = (typeof msg.body  === 'string') ? msg.body : '';
const p = { title: title, body: body, device_key: env.get('BARK_KEY') };
// 透传 bark_* 扩展参数(原 AES 版支持的全部字段)
const map = {bark_level:'level',bark_sound:'sound',bark_url:'url',bark_group:'group',
             bark_copy:'copy',bark_isArchive:'isArchive',bark_icon:'icon',bark_badge:'badge',
             bark_volume:'volume',bark_autoCopy:'autoCopy'};
for (const k in map) { if (msg[k] != null && msg[k] !== false) p[map[k]] = msg[k]; }
msg.payload = p;
msg.sentTitle = title;
msg.sentBody = body;

msg.headers = { 'Content-Type': 'application/json' };
msg.url = env.get('BARK_SERVER') + '/push';
return msg;

// time_parse.js — 自然语言时间解析（Home Assistant 历史查询子流程用）
//
// 把用户表述的中文/英文混合时间，解析成本地时区的 Date（与用户说的墙上时钟一致）。
// 例：昨晚23:12 / 昨天11:00 / 前天08:30 / 今天09:15 / 现在 / 过去8小时 / 8h / 1d /
//     本周 / 本周日 / 2026-07-19T23:12 / 2026-07-19 23:12
//
// 本文件整体可作为 NR function 节点体使用：
//   - 纯函数 parseNaturalTime / toHAISO 在节点作用域内可用；
//   - 底部的 module.exports 守卫在 NR 中会被跳过（NR 不定义 module）。
// 也可被 Node 直接 require 做单元测试。

function _startOfDay(d) {
  const x = new Date(d);
  x.setHours(0, 0, 0, 0);
  return x;
}

function _addDays(d, n) {
  const x = new Date(d);
  x.setDate(x.getDate() + n);
  return x;
}

function _atTime(day, hh, mm, ss) {
  const x = new Date(day);
  x.setHours(hh, mm || 0, ss == null ? 0 : ss, 0);
  return x;
}

// 从文本中搜索 "HH:MM" / "H:MM" / "HH：MM" → [h, m]；否则 null。
// 用搜索（非 ^...$ 锚定），以便 "昨晚23:12" 这类带前缀的表述也能取出时刻。
function _parseHm(s) {
  const m = /(\d{1,2})[:：](\d{1,2})/.exec(s);
  if (!m) return null;
  return [parseInt(m[1], 10), parseInt(m[2], 10)];
}

// 把 Date 格式化为 HA history API 友好的 ISO 8601（带本地时区偏移）。
// HA 内部以 UTC 存储；传入带偏移的 ISO 可被正确换算为该墙上时刻，避免被当成 UTC 而偏移 8 小时。
function toHAISO(d) {
  const off = -d.getTimezoneOffset(); // 分钟，东半球为正
  const sign = off >= 0 ? "+" : "-";
  const abs = Math.abs(off);
  const oh = String(Math.floor(abs / 60)).padStart(2, "0");
  const om = String(abs % 60).padStart(2, "0");
  const Y = d.getFullYear();
  const M = String(d.getMonth() + 1).padStart(2, "0");
  const D = String(d.getDate()).padStart(2, "0");
  const h = String(d.getHours()).padStart(2, "0");
  const mi = String(d.getMinutes()).padStart(2, "0");
  const s = String(d.getSeconds()).padStart(2, "0");
  return `${Y}-${M}-${D}T${h}:${mi}:${s}${sign}${oh}:${om}`;
}

function parseNaturalTime(text, now) {
  if (text == null) return null;
  text = String(text).trim();
  if (!text) return null;
  now = now || new Date();
  const lower = text.toLowerCase();

  // 0) 绝对 ISO 带时刻：2026-07-19T23:12 / 2026-07-19 23:12 / 2026/07/19 23:12
  let m = /^(\d{4})[-/](\d{1,2})[-/](\d{1,2})[ T](\d{1,2})[:：](\d{1,2})/.exec(text);
  if (m) {
    return new Date(+m[1], +m[2] - 1, +m[3], +m[4], +m[5], 0, 0);
  }
  // 仅日期：2026-07-19 → 当天 00:00
  m = /^(\d{4})[-/](\d{1,2})[-/](\d{1,2})$/.exec(text);
  if (m) {
    return _atTime(new Date(+m[1], +m[2] - 1, +m[3]), 0, 0);
  }

  // 1) 紧凑相对：8h / 1d / 24h / 30min
  m = /^(\d+)\s*(h|d|min|m)$/i.exec(lower);
  if (m) {
    const n = parseInt(m[1], 10);
    const u = m[2].toLowerCase();
    const ms = u === "d" ? n * 86400000 : u === "min" || u === "m" ? n * 60000 : n * 3600000;
    return new Date(now.getTime() - ms);
  }

  // 2) 相对偏移：过去8小时 / 8小时前 / 近3天 / 30分钟前 / 2天前
  m = /(?:过去|近)?\s*(\d+)\s*(小时|h|钟头|分钟|min|天|日|d)\s*(前|之内|内|以前)?/.exec(text);
  if (m) {
    const n = parseInt(m[1], 10);
    const unit = m[2];
    let ms;
    if (unit === "分钟" || unit === "min") ms = n * 60000;
    else if (unit === "小时" || unit === "h" || unit === "钟头") ms = n * 3600000;
    else ms = n * 86400000; // 天/日/d
    return new Date(now.getTime() - ms);
  }

  // 3) 现在
  if (/^(现在|目前|此刻|当前|now)$/i.test(lower)) return new Date(now.getTime());

  // 4) 日期词 + 可选时段/时刻
  const dw = /(今天|今日|当天|昨天|昨日|前天|大前天|明天|明日|明早|明晚|明晨|明午|今早|今晨|今午|中午|今晚|昨晚)/.exec(text);
  if (dw) {
    const w = dw[1];
    let base;
    if (w === "今天" || w === "今日" || w === "当天" || w === "今早" || w === "今晨" ||
        w === "今午" || w === "中午" || w === "今晚") {
      base = _startOfDay(now);
    } else if (w === "昨天" || w === "昨日" || w === "昨晚") {
      base = _addDays(_startOfDay(now), -1);
    } else if (w === "前天") {
      base = _addDays(_startOfDay(now), -2);
    } else if (w === "大前天") {
      base = _addDays(_startOfDay(now), -3);
    } else {
      base = _addDays(_startOfDay(now), 1); // 明天/明日/明早/明晚/明晨/明午
    }
    const hm = _parseHm(text);
    let hh = hm ? hm[0] : 0;
    let mm = hm ? hm[1] : 0;
    if (/下午|傍晚|晚上|晚间|明晚|今晚|昨晚/.test(text) && hm && hh < 12) hh += 12;
    if (/凌晨|清晨/.test(text) && hm && hh === 12) hh = 0;
    if (/中午|今午|明午/.test(text) && !hm) { hh = 12; mm = 0; }
    if (/早上|上午|今早|明早|今晨/.test(text) && !hm) { hh = 8; mm = 0; }
    if (/今晚|晚上|傍晚|昨晚/.test(text) && !hm) { hh = 20; mm = 0; } // 晚上无时刻兜底 20:00
    return _atTime(base, hh, mm);
  }

  // 5) 本周日 23:59:59（须先于「本周」判定，否则「本周日」会被「本周」子串抢先）
  if (/本周日|本周末|周日|周天/.test(text)) {
    const d = _startOfDay(now);
    const dow = (d.getDay() + 6) % 7;
    return _atTime(_addDays(d, 6 - dow), 23, 59, 59);
  }
  // 本周一 00:00 / 本周（本周一）
  if (/本周一|本周/.test(text)) {
    const d = _startOfDay(now);
    const dow = (d.getDay() + 6) % 7; // 周一=0
    return _addDays(d, -dow);
  }

  // 6) 仅 HH:MM（无日期词）→ 今天该时刻
  const hm2 = _parseHm(text);
  if (hm2) return _atTime(_startOfDay(now), hm2[0], hm2[1]);

  return null;
}

// 解析一对 [start, end]；end 缺省视为 now。返回 {start, end, start_iso, end_iso} 或 null。
function parseWindow(startText, endText, now) {
  now = now || new Date();
  const s = parseNaturalTime(startText, now);
  if (!s) return null;
  const e = endText ? parseNaturalTime(endText, now) : new Date(now.getTime());
  if (!e) return null;
  return {
    start: s,
    end: e,
    start_iso: toHAISO(s),
    end_iso: toHAISO(e),
  };
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = { parseNaturalTime, toHAISO, parseWindow, _startOfDay, _addDays, _atTime, _parseHm };
}

function _feedNode(msg, start, end) {
  // 注入机制（#107 定论，依据 api-get-history 0.80.3 源码实证，勿再改）：
  // dist/nodes/get-history/index.js 的输入声明为
  //   startDate:{messageProp:["payload.startDate"], configProp:"startDate"}
  //   endDate  :{messageProp:["payload.endDate"],   configProp:"endDate"}
  //   entityId :{messageProp:["payload.entityId"],  configProp:"entityId"}
  // 即节点原生支持经 msg.payload.* 覆盖面板配置（messageProp 优先于 configProp）。
  // 故窗口与实体一律走 msg.payload.* 注入，这是官方支持路径，无需任何节点属性改写。
  //
  // ⚠️ 已废弃路径，勿回退（#107 死结）：曾用 NR 运行时节点查找 API 反查 n_hist 实例并
  // 改写其节点属性。但 function 沙箱内该 API 不可用 → 守卫三元取 null → 其后的 fallback
  // 分支又对同一 API 裸调用 → 必然抛错（进入 fallback 的前提恰恰是该 API 不可用），
  // 子流程整体静默失败。该路径已整体删除，本文件不再留任何运行时节点查找引用。
  //
  // G1.5(#107) 修复：入站 payload 可能是数字/字符串时间戳（实测 at/start 落在 payload）。
  // 旧写法 !msg.payload 对数字/非空字符串为 truthy 不触发重置 → 后续 msg.payload.entityId
  // 给原始值赋属性被 JS 静默忽略 → entityId 注入全失 → ValidationError。
  // 改为：payload 非对象（含数字/字符串/数组/null/undefined）一律重置为空对象后再注入。
  if (!msg.payload || typeof msg.payload !== "object" || Array.isArray(msg.payload)) {
    msg.payload = {};
  }
  msg.payload.startDate = toHAISO(start);
  msg.payload.endDate = toHAISO(end);
  msg.payload.entityId = msg.entity || "";
  return msg;
}

const now = new Date();
let s = parseNaturalTime(msg.start, now);
// end 缺省（未给 / 解析不出）→ now+60s，语义=「查到现在」
let e = parseNaturalTime(msg.end, now) || new Date(now.getTime() + 60000);
// ⚠️ #118 修复，勿回退为「过去 end 一律钳到 now」：
//   旧代码 `if (e < now) e = now+60s` 的立论是「api-get-history 对过去 endDate 返回空数组」，
//   该前提【已实测证伪】——GetHistoryController 只是把 endDate 原样透传给
//   HA /api/history/period 的 end_time，过去时间正常返回数据（2026-08-04 实测：
//   昨天00:00→今天00:00 返回 11 条）。旧钳位会把用户显式指定的过去 end 偷偷改成「现在」，
//   使「昨天00:00→今天00:00」变成「昨天00:00→现在」，把今天的数据混进昨天的统计
//   （实测 mean(temperature) 24.7 被污染成 24.909）。
// 现在只钳【未来】end：未来时刻尚无历史，钳到 now 才有意义。
if (e.getTime() > now.getTime()) e = new Date(now.getTime() + 60000);
// G1 future-guard：未来 start（如凌晨跑「今日08:00」）→ 钳到 now，避免 start>end 反向窗口
// → HA 抛 ValidationError: startDate must be a valid date；并兜底交换防反向窗口。
if (s && s.getTime() > now.getTime()) s = new Date(now.getTime());
if (s && e && s.getTime() > e.getTime()) { const _t = s; s = e; e = _t; }
msg._hist_start = toHAISO(s);
msg._hist_end = toHAISO(e);
return _feedNode(msg, s, e);

// HA 取数失败（404 无历史 / 网络 / 鉴权）→ 降级为空结果数组，
// 让 compute 函数返回 found=false / occurred=false / duration=0 等结构化空答案，
// 而非让消息丢失导致下游『分支』中断。
msg._hist_error = (msg.error && (msg.error.message || String(msg.error))) || 'unknown';
msg.payload = [];
return msg;

// compute.js — 历史查询 4 类计算（在 NR function 节点内执行）。
// 输入：msg.payload 为 api-get-history 返回的状态数组（HA history REST 形状）。
// 状态条目假设形状：{ entity_id, state, attributes, last_changed, last_updated }
//   - 取值：attribute 给定 → entry.attributes[attribute]；否则 → entry.state
//   - 时间：用 last_changed（状态变化时刻）作为该条状态的有效起点
// 输出：把答案对象写回 msg.payload（供下游『提取/分支』读取）。
//
// 本文件可作 Node 模块 require（module.exports 守卫在 NR 中被跳过）。
// 能量统计（energy）走 statistics 而非 history，由 build_subflows.py 另配 REST 节点，
// 此处 computeEnergy 解析 statistics 桶（sum change 字段）。

function _valOf(entry, attribute) {
  if (attribute) {
    const a = entry.attributes || {};
    return (a[attribute] !== undefined) ? a[attribute] : entry.state;
  }
  return entry.state;
}

function _tsOf(entry) {
  const t = entry.last_changed || entry.last_updated || entry.lu || entry.lc;
  return t ? new Date(t).getTime() : NaN;
}

function _valOfAttr(entry, attribute) {
  return _valOf(entry, attribute);
}

// HA 的 /api/history/period 在某些版本会把单实体历史包成 [[...]]（外层数组只含
// 一个内层数组）。api-get-history 节点可能原样透传。若首元素仍是数组则拍平一层，
// 否则 compute* 会拿 wrapper 当 entry（_tsOf 返回 NaN → best=null → 静默 found=false）。
function _ensureFlat(arr) {
  if (Array.isArray(arr) && arr.length && Array.isArray(arr[0])) {
    return arr[0];
  }
  return arr;
}

// 1) 某时刻状态：as-of 语义 —— 取【目标时刻及之前】最后一次采样。
//
// ⚠️ #118 修复，勿回退为 Math.abs 最近邻：
//   状态是阶跃保持的（一次变化后一直有效到下次变化），所以「T 时刻的状态」= T 之前
//   最后一次变化后的值。旧实现按 |t-target| 取绝对最近，会选到 target【之后】的采样，
//   等于用未来状态回答过去问题。
//   实测反例（2026-08-04，climate.lumi_v3_db16_air_conditioner，目标 2026-08-03T23:12+08）：
//     采样 15:12:00Z='off'（目标前 6h，窗口边界态） / 15:34:31Z='cool'（目标后 22min）
//     旧实现 → 'cool'（错，那时空调还没开）；as-of → 'off'（对）。
//   HA /api/history/period 会在窗口起点合成一条「当时生效状态」，故只要 target 落在
//   窗口内，几乎总能找到 t<=target 的采样。
// 找不到前驱时（target 早于窗口起点）回退最近后继，并用 source='after_target' 显式标注，
// 让下游能区分「确证值」与「近似值」，而不是静默给出可疑答案。
function computeStateAt(msg, arr) {
  arr = _ensureFlat(arr);
  const target = new Date(msg._hist_target).getTime();
  const miss = () => ({
    found: false, entity: msg.entity, at_iso: msg._hist_target_iso,
    value: null, attribute: msg.attribute || null, nearest_ts: null, source: null
  });
  if (!arr || !arr.length) return miss();
  let asOf = null, asOfT = -Infinity;   // t <= target 中最晚的
  let after = null, afterT = Infinity;  // t >  target 中最早的
  for (const e of arr) {
    const t = _tsOf(e);
    if (isNaN(t)) continue;
    if (t <= target) {
      if (t > asOfT) { asOfT = t; asOf = e; }
    } else if (t < afterT) { afterT = t; after = e; }
  }
  const best = asOf || after;
  if (!best) return miss();
  return {
    found: true, entity: msg.entity, at_iso: msg._hist_target_iso,
    value: _valOf(best, msg.attribute), attribute: msg.attribute || null,
    unit: (best.attributes && best.attributes.unit_of_measurement) || null,
    nearest_ts: new Date(_tsOf(best)).toISOString(),
    // 'as_of'       = 目标时刻确实生效的状态（可信）
    // 'after_target'= 目标早于可用历史，返回的是其后最近采样（近似，下游可据此降级措辞）
    source: asOf ? "as_of" : "after_target"
  };
}

// 2) 区间内是否发生（状态变化 / 达到某态）
function computeOccurred(msg, arr) {
  arr = _ensureFlat(arr);
  const start = new Date(msg._hist_start).getTime();
  const end = new Date(msg._hist_end).getTime();
  const want = msg.state; // 目标态；undefined → 任意变化
  const attr = msg.attribute;
  let count = 0;
  const events = [];
  let prev = null;
  for (const e of arr) {
    const t = _tsOf(e);
    if (isNaN(t)) continue;
    if (t < start || t > end) { prev = { v: _valOfAttr(e, attr), t }; continue; }
    const v = _valOfAttr(e, attr);
    if (prev && prev.v !== v) {
      // ⚠️ #118 修复，勿回退加回 `prev.v === want`：
      //   指定 state 时只计「变成 want」的次数。旧实现把「离开 want」也计入，
      //   导致次数翻倍。实测（2026-08-03 空调 state='off'）旧版 count=4，
      //   明细为 cool→off / off→cool / cool→off / off→cool，真正「变成 off」只有 2 次。
      if (!want ? true : v === want) {
        count++;
        events.push({ ts: new Date(t).toISOString(), from: prev.v, to: v });
      }
    } else if (!prev) {
      // 窗口内第一条采样即处于目标态（HA 会在窗口起点合成当时生效状态）→ 记 1 次
      if (want && v === want) { count++; events.push({ ts: new Date(t).toISOString(), from: null, to: v }); }
    }
    prev = { v, t };
  }
  return {
    occurred: count > 0, entity: msg.entity,
    start_iso: msg._hist_start, end_iso: msg._hist_end,
    count, state: want || null,
    events,
    first_ts: events.length ? events[0].ts : null,
    last_ts: events.length ? events[events.length - 1].ts : null
  };
}

// 3) 区间内处于某态的累计时长
function computeDuration(msg, arr) {
  arr = _ensureFlat(arr);
  const start = new Date(msg._hist_start).getTime();
  const end = new Date(msg._hist_end).getTime();
  const want = msg.state;
  const attr = msg.attribute;
  let total = 0;
  let prev = null;
  for (const e of arr) {
    const t = _tsOf(e);
    if (isNaN(t)) continue;
    const v = _valOfAttr(e, attr);
    if (prev) {
      const segStart = Math.max(prev.t, start);
      const segEnd = Math.min(t, end);
      if (segEnd > segStart && prev.v === want) total += (segEnd - segStart);
    }
    prev = { v, t };
  }
  if (prev && prev.v === want) {
    const segStart = Math.max(prev.t, start);
    if (end > segStart) total += (end - segStart);
  }
  const sec = Math.floor(total / 1000);
  const h = Math.floor(sec / 3600), m = Math.floor((sec % 3600) / 60), s = sec % 60;
  const human = (h > 0 ? h + "小时" : "") + (m > 0 ? m + "分" : "") +
    (s > 0 || (h === 0 && m === 0) ? s + "秒" : "");
  return {
    total_seconds: sec, total_human: human || "0秒", entity: msg.entity,
    start_iso: msg._hist_start, end_iso: msg._hist_end, state: want,
    ratio: (end > start) ? +(total / (end - start)).toFixed(4) : 0
  };
}

// 4a) 聚合：count / mean / min / max / sum（基于 history 数组的数值属性）
function computeAggregate(msg, arr) {
  arr = _ensureFlat(arr);
  const metric = msg.metric;
  const attr = msg.attribute;
  if (metric === "count") {
    let count = 0, prev = null;
    for (const e of arr) {
      const v = _valOfAttr(e, attr);
      if (prev && prev !== v) count++;
      else if (!prev) count++;
      prev = v;
    }
    return { value: count, unit: "次", entity: msg.entity,
      start_iso: msg._hist_start, end_iso: msg._hist_end, metric, attribute: attr || null };
  }
  const nums = [];
  let unit = null;
  for (const e of arr) {
    const raw = attr ? _valOfAttr(e, attr) : e.state;
    const n = parseFloat(raw);
    if (!isNaN(n)) {
      nums.push(n);
      // 取首个可用的 unit_of_measurement（#118：旧版恒为 null，下游拿不到量纲）
      if (unit === null && e.attributes && e.attributes.unit_of_measurement) {
        unit = e.attributes.unit_of_measurement;
      }
    }
  }
  if (!nums.length) {
    return { value: null, unit: null, entity: msg.entity,
      start_iso: msg._hist_start, end_iso: msg._hist_end, metric,
      attribute: attr || null, samples: 0, error: "无数值数据" };
  }
  let value;
  if (metric === "mean") value = nums.reduce((a, b) => a + b, 0) / nums.length;
  else if (metric === "min") value = Math.min.apply(null, nums);
  else if (metric === "max") value = Math.max.apply(null, nums);
  else if (metric === "sum") value = nums.reduce((a, b) => a + b, 0);
  // ⚠️ mean 为【采样算术均值】而非时间加权均值：采样密集的时段权重更高。
  //    需要时间加权请另开 metric（当前语义保持与旧版一致，避免静默改变已有 flow 的结果）。
  return { value, unit, entity: msg.entity,
    start_iso: msg._hist_start, end_iso: msg._hist_end, metric,
    attribute: attr || null, samples: nums.length };
}

// 4b) 能量聚合：解析 statistics REST 返回的桶数组，累加每段 change（kWh）
// statistics 响应形状（HA）：{ "<statistic_id>": [ {start, end, mean, sum, change, ...}, ... ] }
function computeEnergy(msg, statObj) {
  const buckets = (statObj && typeof statObj === "object")
    ? Object.values(statObj).flat() : [];
  let kwh = 0;
  for (const b of buckets) {
    const c = (b && (b.change != null)) ? parseFloat(b.change) : NaN;
    if (!isNaN(c)) kwh += c;
  }
  return {
    value: +kwh.toFixed(3), unit: "kWh", entity: msg.entity,
    start_iso: msg._hist_start, end_iso: msg._hist_end,
    metric: "energy", attribute: msg.attribute || "energy"
  };
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = {
    computeStateAt, computeOccurred, computeDuration,
    computeAggregate, computeEnergy, _valOf, _tsOf, _valOfAttr
  };
}

const arr = msg.payload || [];
if (msg.metric === 'energy') { msg.payload = computeEnergy(msg, msg.payload); }
else { msg.payload = computeAggregate(msg, arr); }
return msg;

// time_parse.js — 自然语言时间解析（Home Assistant 历史查询子流程用）
//
// 把用户表述的中文/英文混合时间，解析成本地时区的 Date（与用户说的墙上时钟一致）。
// 例：昨晚23:12 / 昨天11:00 / 前天08:30 / 今天09:15 / 现在 / 过去8小时 / 8h / 1d /
//     本周 / 本周日 / 2026-07-19T23:12 / 2026-07-19 23:12
//
// 本文件整体可作为 NR function 节点体使用：
//   - 纯函数 parseNaturalTime / toHAISO 在节点作用域内可用；
//   - 底部的 module.exports 守卫在 NR 中会被跳过（NR 不定义 module）。
// 也可被 Node 直接 require 做单元测试。

function _startOfDay(d) {
  const x = new Date(d);
  x.setHours(0, 0, 0, 0);
  return x;
}

function _addDays(d, n) {
  const x = new Date(d);
  x.setDate(x.getDate() + n);
  return x;
}

function _atTime(day, hh, mm, ss) {
  const x = new Date(day);
  x.setHours(hh, mm || 0, ss == null ? 0 : ss, 0);
  return x;
}

// 从文本中搜索 "HH:MM" / "H:MM" / "HH：MM" → [h, m]；否则 null。
// 用搜索（非 ^...$ 锚定），以便 "昨晚23:12" 这类带前缀的表述也能取出时刻。
function _parseHm(s) {
  const m = /(\d{1,2})[:：](\d{1,2})/.exec(s);
  if (!m) return null;
  return [parseInt(m[1], 10), parseInt(m[2], 10)];
}

// 把 Date 格式化为 HA history API 友好的 ISO 8601（带本地时区偏移）。
// HA 内部以 UTC 存储；传入带偏移的 ISO 可被正确换算为该墙上时刻，避免被当成 UTC 而偏移 8 小时。
function toHAISO(d) {
  const off = -d.getTimezoneOffset(); // 分钟，东半球为正
  const sign = off >= 0 ? "+" : "-";
  const abs = Math.abs(off);
  const oh = String(Math.floor(abs / 60)).padStart(2, "0");
  const om = String(abs % 60).padStart(2, "0");
  const Y = d.getFullYear();
  const M = String(d.getMonth() + 1).padStart(2, "0");
  const D = String(d.getDate()).padStart(2, "0");
  const h = String(d.getHours()).padStart(2, "0");
  const mi = String(d.getMinutes()).padStart(2, "0");
  const s = String(d.getSeconds()).padStart(2, "0");
  return `${Y}-${M}-${D}T${h}:${mi}:${s}${sign}${oh}:${om}`;
}

function parseNaturalTime(text, now) {
  if (text == null) return null;
  text = String(text).trim();
  if (!text) return null;
  now = now || new Date();
  const lower = text.toLowerCase();

  // 0) 绝对 ISO 带时刻：2026-07-19T23:12 / 2026-07-19 23:12 / 2026/07/19 23:12
  let m = /^(\d{4})[-/](\d{1,2})[-/](\d{1,2})[ T](\d{1,2})[:：](\d{1,2})/.exec(text);
  if (m) {
    return new Date(+m[1], +m[2] - 1, +m[3], +m[4], +m[5], 0, 0);
  }
  // 仅日期：2026-07-19 → 当天 00:00
  m = /^(\d{4})[-/](\d{1,2})[-/](\d{1,2})$/.exec(text);
  if (m) {
    return _atTime(new Date(+m[1], +m[2] - 1, +m[3]), 0, 0);
  }

  // 1) 紧凑相对：8h / 1d / 24h / 30min
  m = /^(\d+)\s*(h|d|min|m)$/i.exec(lower);
  if (m) {
    const n = parseInt(m[1], 10);
    const u = m[2].toLowerCase();
    const ms = u === "d" ? n * 86400000 : u === "min" || u === "m" ? n * 60000 : n * 3600000;
    return new Date(now.getTime() - ms);
  }

  // 2) 相对偏移：过去8小时 / 8小时前 / 近3天 / 30分钟前 / 2天前
  m = /(?:过去|近)?\s*(\d+)\s*(小时|h|钟头|分钟|min|天|日|d)\s*(前|之内|内|以前)?/.exec(text);
  if (m) {
    const n = parseInt(m[1], 10);
    const unit = m[2];
    let ms;
    if (unit === "分钟" || unit === "min") ms = n * 60000;
    else if (unit === "小时" || unit === "h" || unit === "钟头") ms = n * 3600000;
    else ms = n * 86400000; // 天/日/d
    return new Date(now.getTime() - ms);
  }

  // 3) 现在
  if (/^(现在|目前|此刻|当前|now)$/i.test(lower)) return new Date(now.getTime());

  // 4) 日期词 + 可选时段/时刻
  const dw = /(今天|今日|当天|昨天|昨日|前天|大前天|明天|明日|明早|明晚|明晨|明午|今早|今晨|今午|中午|今晚|昨晚)/.exec(text);
  if (dw) {
    const w = dw[1];
    let base;
    if (w === "今天" || w === "今日" || w === "当天" || w === "今早" || w === "今晨" ||
        w === "今午" || w === "中午" || w === "今晚") {
      base = _startOfDay(now);
    } else if (w === "昨天" || w === "昨日" || w === "昨晚") {
      base = _addDays(_startOfDay(now), -1);
    } else if (w === "前天") {
      base = _addDays(_startOfDay(now), -2);
    } else if (w === "大前天") {
      base = _addDays(_startOfDay(now), -3);
    } else {
      base = _addDays(_startOfDay(now), 1); // 明天/明日/明早/明晚/明晨/明午
    }
    const hm = _parseHm(text);
    let hh = hm ? hm[0] : 0;
    let mm = hm ? hm[1] : 0;
    if (/下午|傍晚|晚上|晚间|明晚|今晚|昨晚/.test(text) && hm && hh < 12) hh += 12;
    if (/凌晨|清晨/.test(text) && hm && hh === 12) hh = 0;
    if (/中午|今午|明午/.test(text) && !hm) { hh = 12; mm = 0; }
    if (/早上|上午|今早|明早|今晨/.test(text) && !hm) { hh = 8; mm = 0; }
    if (/今晚|晚上|傍晚|昨晚/.test(text) && !hm) { hh = 20; mm = 0; } // 晚上无时刻兜底 20:00
    return _atTime(base, hh, mm);
  }

  // 5) 本周日 23:59:59（须先于「本周」判定，否则「本周日」会被「本周」子串抢先）
  if (/本周日|本周末|周日|周天/.test(text)) {
    const d = _startOfDay(now);
    const dow = (d.getDay() + 6) % 7;
    return _atTime(_addDays(d, 6 - dow), 23, 59, 59);
  }
  // 本周一 00:00 / 本周（本周一）
  if (/本周一|本周/.test(text)) {
    const d = _startOfDay(now);
    const dow = (d.getDay() + 6) % 7; // 周一=0
    return _addDays(d, -dow);
  }

  // 6) 仅 HH:MM（无日期词）→ 今天该时刻
  const hm2 = _parseHm(text);
  if (hm2) return _atTime(_startOfDay(now), hm2[0], hm2[1]);

  return null;
}

// 解析一对 [start, end]；end 缺省视为 now。返回 {start, end, start_iso, end_iso} 或 null。
function parseWindow(startText, endText, now) {
  now = now || new Date();
  const s = parseNaturalTime(startText, now);
  if (!s) return null;
  const e = endText ? parseNaturalTime(endText, now) : new Date(now.getTime());
  if (!e) return null;
  return {
    start: s,
    end: e,
    start_iso: toHAISO(s),
    end_iso: toHAISO(e),
  };
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = { parseNaturalTime, toHAISO, parseWindow, _startOfDay, _addDays, _atTime, _parseHm };
}

function _feedNode(msg, start, end) {
  // 注入机制（#107 定论，依据 api-get-history 0.80.3 源码实证，勿再改）：
  // dist/nodes/get-history/index.js 的输入声明为
  //   startDate:{messageProp:["payload.startDate"], configProp:"startDate"}
  //   endDate  :{messageProp:["payload.endDate"],   configProp:"endDate"}
  //   entityId :{messageProp:["payload.entityId"],  configProp:"entityId"}
  // 即节点原生支持经 msg.payload.* 覆盖面板配置（messageProp 优先于 configProp）。
  // 故窗口与实体一律走 msg.payload.* 注入，这是官方支持路径，无需任何节点属性改写。
  //
  // ⚠️ 已废弃路径，勿回退（#107 死结）：曾用 NR 运行时节点查找 API 反查 n_hist 实例并
  // 改写其节点属性。但 function 沙箱内该 API 不可用 → 守卫三元取 null → 其后的 fallback
  // 分支又对同一 API 裸调用 → 必然抛错（进入 fallback 的前提恰恰是该 API 不可用），
  // 子流程整体静默失败。该路径已整体删除，本文件不再留任何运行时节点查找引用。
  //
  // G1.5(#107) 修复：入站 payload 可能是数字/字符串时间戳（实测 at/start 落在 payload）。
  // 旧写法 !msg.payload 对数字/非空字符串为 truthy 不触发重置 → 后续 msg.payload.entityId
  // 给原始值赋属性被 JS 静默忽略 → entityId 注入全失 → ValidationError。
  // 改为：payload 非对象（含数字/字符串/数组/null/undefined）一律重置为空对象后再注入。
  if (!msg.payload || typeof msg.payload !== "object" || Array.isArray(msg.payload)) {
    msg.payload = {};
  }
  msg.payload.startDate = toHAISO(start);
  msg.payload.endDate = toHAISO(end);
  msg.payload.entityId = msg.entity || "";
  return msg;
}

const now = new Date();
let s = parseNaturalTime(msg.start, now);
// end 缺省（未给 / 解析不出）→ now+60s，语义=「查到现在」
let e = parseNaturalTime(msg.end, now) || new Date(now.getTime() + 60000);
// ⚠️ #118 修复，勿回退为「过去 end 一律钳到 now」：
//   旧代码 `if (e < now) e = now+60s` 的立论是「api-get-history 对过去 endDate 返回空数组」，
//   该前提【已实测证伪】——GetHistoryController 只是把 endDate 原样透传给
//   HA /api/history/period 的 end_time，过去时间正常返回数据（2026-08-04 实测：
//   昨天00:00→今天00:00 返回 11 条）。旧钳位会把用户显式指定的过去 end 偷偷改成「现在」，
//   使「昨天00:00→今天00:00」变成「昨天00:00→现在」，把今天的数据混进昨天的统计
//   （实测 mean(temperature) 24.7 被污染成 24.909）。
// 现在只钳【未来】end：未来时刻尚无历史，钳到 now 才有意义。
if (e.getTime() > now.getTime()) e = new Date(now.getTime() + 60000);
// G1 future-guard：未来 start（如凌晨跑「今日08:00」）→ 钳到 now，避免 start>end 反向窗口
// → HA 抛 ValidationError: startDate must be a valid date；并兜底交换防反向窗口。
if (s && s.getTime() > now.getTime()) s = new Date(now.getTime());
if (s && e && s.getTime() > e.getTime()) { const _t = s; s = e; e = _t; }
msg._hist_start = toHAISO(s);
msg._hist_end = toHAISO(e);
return _feedNode(msg, s, e);

// HA 取数失败（404 无历史 / 网络 / 鉴权）→ 降级为空结果数组，
// 让 compute 函数返回 found=false / occurred=false / duration=0 等结构化空答案，
// 而非让消息丢失导致下游『分支』中断。
msg._hist_error = (msg.error && (msg.error.message || String(msg.error))) || 'unknown';
msg.payload = [];
return msg;

// compute.js — 历史查询 4 类计算（在 NR function 节点内执行）。
// 输入：msg.payload 为 api-get-history 返回的状态数组（HA history REST 形状）。
// 状态条目假设形状：{ entity_id, state, attributes, last_changed, last_updated }
//   - 取值：attribute 给定 → entry.attributes[attribute]；否则 → entry.state
//   - 时间：用 last_changed（状态变化时刻）作为该条状态的有效起点
// 输出：把答案对象写回 msg.payload（供下游『提取/分支』读取）。
//
// 本文件可作 Node 模块 require（module.exports 守卫在 NR 中被跳过）。
// 能量统计（energy）走 statistics 而非 history，由 build_subflows.py 另配 REST 节点，
// 此处 computeEnergy 解析 statistics 桶（sum change 字段）。

function _valOf(entry, attribute) {
  if (attribute) {
    const a = entry.attributes || {};
    return (a[attribute] !== undefined) ? a[attribute] : entry.state;
  }
  return entry.state;
}

function _tsOf(entry) {
  const t = entry.last_changed || entry.last_updated || entry.lu || entry.lc;
  return t ? new Date(t).getTime() : NaN;
}

function _valOfAttr(entry, attribute) {
  return _valOf(entry, attribute);
}

// HA 的 /api/history/period 在某些版本会把单实体历史包成 [[...]]（外层数组只含
// 一个内层数组）。api-get-history 节点可能原样透传。若首元素仍是数组则拍平一层，
// 否则 compute* 会拿 wrapper 当 entry（_tsOf 返回 NaN → best=null → 静默 found=false）。
function _ensureFlat(arr) {
  if (Array.isArray(arr) && arr.length && Array.isArray(arr[0])) {
    return arr[0];
  }
  return arr;
}

// 1) 某时刻状态：as-of 语义 —— 取【目标时刻及之前】最后一次采样。
//
// ⚠️ #118 修复，勿回退为 Math.abs 最近邻：
//   状态是阶跃保持的（一次变化后一直有效到下次变化），所以「T 时刻的状态」= T 之前
//   最后一次变化后的值。旧实现按 |t-target| 取绝对最近，会选到 target【之后】的采样，
//   等于用未来状态回答过去问题。
//   实测反例（2026-08-04，climate.lumi_v3_db16_air_conditioner，目标 2026-08-03T23:12+08）：
//     采样 15:12:00Z='off'（目标前 6h，窗口边界态） / 15:34:31Z='cool'（目标后 22min）
//     旧实现 → 'cool'（错，那时空调还没开）；as-of → 'off'（对）。
//   HA /api/history/period 会在窗口起点合成一条「当时生效状态」，故只要 target 落在
//   窗口内，几乎总能找到 t<=target 的采样。
// 找不到前驱时（target 早于窗口起点）回退最近后继，并用 source='after_target' 显式标注，
// 让下游能区分「确证值」与「近似值」，而不是静默给出可疑答案。
function computeStateAt(msg, arr) {
  arr = _ensureFlat(arr);
  const target = new Date(msg._hist_target).getTime();
  const miss = () => ({
    found: false, entity: msg.entity, at_iso: msg._hist_target_iso,
    value: null, attribute: msg.attribute || null, nearest_ts: null, source: null
  });
  if (!arr || !arr.length) return miss();
  let asOf = null, asOfT = -Infinity;   // t <= target 中最晚的
  let after = null, afterT = Infinity;  // t >  target 中最早的
  for (const e of arr) {
    const t = _tsOf(e);
    if (isNaN(t)) continue;
    if (t <= target) {
      if (t > asOfT) { asOfT = t; asOf = e; }
    } else if (t < afterT) { afterT = t; after = e; }
  }
  const best = asOf || after;
  if (!best) return miss();
  return {
    found: true, entity: msg.entity, at_iso: msg._hist_target_iso,
    value: _valOf(best, msg.attribute), attribute: msg.attribute || null,
    unit: (best.attributes && best.attributes.unit_of_measurement) || null,
    nearest_ts: new Date(_tsOf(best)).toISOString(),
    // 'as_of'       = 目标时刻确实生效的状态（可信）
    // 'after_target'= 目标早于可用历史，返回的是其后最近采样（近似，下游可据此降级措辞）
    source: asOf ? "as_of" : "after_target"
  };
}

// 2) 区间内是否发生（状态变化 / 达到某态）
function computeOccurred(msg, arr) {
  arr = _ensureFlat(arr);
  const start = new Date(msg._hist_start).getTime();
  const end = new Date(msg._hist_end).getTime();
  const want = msg.state; // 目标态；undefined → 任意变化
  const attr = msg.attribute;
  let count = 0;
  const events = [];
  let prev = null;
  for (const e of arr) {
    const t = _tsOf(e);
    if (isNaN(t)) continue;
    if (t < start || t > end) { prev = { v: _valOfAttr(e, attr), t }; continue; }
    const v = _valOfAttr(e, attr);
    if (prev && prev.v !== v) {
      // ⚠️ #118 修复，勿回退加回 `prev.v === want`：
      //   指定 state 时只计「变成 want」的次数。旧实现把「离开 want」也计入，
      //   导致次数翻倍。实测（2026-08-03 空调 state='off'）旧版 count=4，
      //   明细为 cool→off / off→cool / cool→off / off→cool，真正「变成 off」只有 2 次。
      if (!want ? true : v === want) {
        count++;
        events.push({ ts: new Date(t).toISOString(), from: prev.v, to: v });
      }
    } else if (!prev) {
      // 窗口内第一条采样即处于目标态（HA 会在窗口起点合成当时生效状态）→ 记 1 次
      if (want && v === want) { count++; events.push({ ts: new Date(t).toISOString(), from: null, to: v }); }
    }
    prev = { v, t };
  }
  return {
    occurred: count > 0, entity: msg.entity,
    start_iso: msg._hist_start, end_iso: msg._hist_end,
    count, state: want || null,
    events,
    first_ts: events.length ? events[0].ts : null,
    last_ts: events.length ? events[events.length - 1].ts : null
  };
}

// 3) 区间内处于某态的累计时长
function computeDuration(msg, arr) {
  arr = _ensureFlat(arr);
  const start = new Date(msg._hist_start).getTime();
  const end = new Date(msg._hist_end).getTime();
  const want = msg.state;
  const attr = msg.attribute;
  let total = 0;
  let prev = null;
  for (const e of arr) {
    const t = _tsOf(e);
    if (isNaN(t)) continue;
    const v = _valOfAttr(e, attr);
    if (prev) {
      const segStart = Math.max(prev.t, start);
      const segEnd = Math.min(t, end);
      if (segEnd > segStart && prev.v === want) total += (segEnd - segStart);
    }
    prev = { v, t };
  }
  if (prev && prev.v === want) {
    const segStart = Math.max(prev.t, start);
    if (end > segStart) total += (end - segStart);
  }
  const sec = Math.floor(total / 1000);
  const h = Math.floor(sec / 3600), m = Math.floor((sec % 3600) / 60), s = sec % 60;
  const human = (h > 0 ? h + "小时" : "") + (m > 0 ? m + "分" : "") +
    (s > 0 || (h === 0 && m === 0) ? s + "秒" : "");
  return {
    total_seconds: sec, total_human: human || "0秒", entity: msg.entity,
    start_iso: msg._hist_start, end_iso: msg._hist_end, state: want,
    ratio: (end > start) ? +(total / (end - start)).toFixed(4) : 0
  };
}

// 4a) 聚合：count / mean / min / max / sum（基于 history 数组的数值属性）
function computeAggregate(msg, arr) {
  arr = _ensureFlat(arr);
  const metric = msg.metric;
  const attr = msg.attribute;
  if (metric === "count") {
    let count = 0, prev = null;
    for (const e of arr) {
      const v = _valOfAttr(e, attr);
      if (prev && prev !== v) count++;
      else if (!prev) count++;
      prev = v;
    }
    return { value: count, unit: "次", entity: msg.entity,
      start_iso: msg._hist_start, end_iso: msg._hist_end, metric, attribute: attr || null };
  }
  const nums = [];
  let unit = null;
  for (const e of arr) {
    const raw = attr ? _valOfAttr(e, attr) : e.state;
    const n = parseFloat(raw);
    if (!isNaN(n)) {
      nums.push(n);
      // 取首个可用的 unit_of_measurement（#118：旧版恒为 null，下游拿不到量纲）
      if (unit === null && e.attributes && e.attributes.unit_of_measurement) {
        unit = e.attributes.unit_of_measurement;
      }
    }
  }
  if (!nums.length) {
    return { value: null, unit: null, entity: msg.entity,
      start_iso: msg._hist_start, end_iso: msg._hist_end, metric,
      attribute: attr || null, samples: 0, error: "无数值数据" };
  }
  let value;
  if (metric === "mean") value = nums.reduce((a, b) => a + b, 0) / nums.length;
  else if (metric === "min") value = Math.min.apply(null, nums);
  else if (metric === "max") value = Math.max.apply(null, nums);
  else if (metric === "sum") value = nums.reduce((a, b) => a + b, 0);
  // ⚠️ mean 为【采样算术均值】而非时间加权均值：采样密集的时段权重更高。
  //    需要时间加权请另开 metric（当前语义保持与旧版一致，避免静默改变已有 flow 的结果）。
  return { value, unit, entity: msg.entity,
    start_iso: msg._hist_start, end_iso: msg._hist_end, metric,
    attribute: attr || null, samples: nums.length };
}

// 4b) 能量聚合：解析 statistics REST 返回的桶数组，累加每段 change（kWh）
// statistics 响应形状（HA）：{ "<statistic_id>": [ {start, end, mean, sum, change, ...}, ... ] }
function computeEnergy(msg, statObj) {
  const buckets = (statObj && typeof statObj === "object")
    ? Object.values(statObj).flat() : [];
  let kwh = 0;
  for (const b of buckets) {
    const c = (b && (b.change != null)) ? parseFloat(b.change) : NaN;
    if (!isNaN(c)) kwh += c;
  }
  return {
    value: +kwh.toFixed(3), unit: "kWh", entity: msg.entity,
    start_iso: msg._hist_start, end_iso: msg._hist_end,
    metric: "energy", attribute: msg.attribute || "energy"
  };
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = {
    computeStateAt, computeOccurred, computeDuration,
    computeAggregate, computeEnergy, _valOf, _tsOf, _valOfAttr
  };
}

const arr = msg.payload || [];
msg.payload = computeDuration(msg, arr);
return msg;

// time_parse.js — 自然语言时间解析（Home Assistant 历史查询子流程用）
//
// 把用户表述的中文/英文混合时间，解析成本地时区的 Date（与用户说的墙上时钟一致）。
// 例：昨晚23:12 / 昨天11:00 / 前天08:30 / 今天09:15 / 现在 / 过去8小时 / 8h / 1d /
//     本周 / 本周日 / 2026-07-19T23:12 / 2026-07-19 23:12
//
// 本文件整体可作为 NR function 节点体使用：
//   - 纯函数 parseNaturalTime / toHAISO 在节点作用域内可用；
//   - 底部的 module.exports 守卫在 NR 中会被跳过（NR 不定义 module）。
// 也可被 Node 直接 require 做单元测试。

function _startOfDay(d) {
  const x = new Date(d);
  x.setHours(0, 0, 0, 0);
  return x;
}

function _addDays(d, n) {
  const x = new Date(d);
  x.setDate(x.getDate() + n);
  return x;
}

function _atTime(day, hh, mm, ss) {
  const x = new Date(day);
  x.setHours(hh, mm || 0, ss == null ? 0 : ss, 0);
  return x;
}

// 从文本中搜索 "HH:MM" / "H:MM" / "HH：MM" → [h, m]；否则 null。
// 用搜索（非 ^...$ 锚定），以便 "昨晚23:12" 这类带前缀的表述也能取出时刻。
function _parseHm(s) {
  const m = /(\d{1,2})[:：](\d{1,2})/.exec(s);
  if (!m) return null;
  return [parseInt(m[1], 10), parseInt(m[2], 10)];
}

// 把 Date 格式化为 HA history API 友好的 ISO 8601（带本地时区偏移）。
// HA 内部以 UTC 存储；传入带偏移的 ISO 可被正确换算为该墙上时刻，避免被当成 UTC 而偏移 8 小时。
function toHAISO(d) {
  const off = -d.getTimezoneOffset(); // 分钟，东半球为正
  const sign = off >= 0 ? "+" : "-";
  const abs = Math.abs(off);
  const oh = String(Math.floor(abs / 60)).padStart(2, "0");
  const om = String(abs % 60).padStart(2, "0");
  const Y = d.getFullYear();
  const M = String(d.getMonth() + 1).padStart(2, "0");
  const D = String(d.getDate()).padStart(2, "0");
  const h = String(d.getHours()).padStart(2, "0");
  const mi = String(d.getMinutes()).padStart(2, "0");
  const s = String(d.getSeconds()).padStart(2, "0");
  return `${Y}-${M}-${D}T${h}:${mi}:${s}${sign}${oh}:${om}`;
}

function parseNaturalTime(text, now) {
  if (text == null) return null;
  text = String(text).trim();
  if (!text) return null;
  now = now || new Date();
  const lower = text.toLowerCase();

  // 0) 绝对 ISO 带时刻：2026-07-19T23:12 / 2026-07-19 23:12 / 2026/07/19 23:12
  let m = /^(\d{4})[-/](\d{1,2})[-/](\d{1,2})[ T](\d{1,2})[:：](\d{1,2})/.exec(text);
  if (m) {
    return new Date(+m[1], +m[2] - 1, +m[3], +m[4], +m[5], 0, 0);
  }
  // 仅日期：2026-07-19 → 当天 00:00
  m = /^(\d{4})[-/](\d{1,2})[-/](\d{1,2})$/.exec(text);
  if (m) {
    return _atTime(new Date(+m[1], +m[2] - 1, +m[3]), 0, 0);
  }

  // 1) 紧凑相对：8h / 1d / 24h / 30min
  m = /^(\d+)\s*(h|d|min|m)$/i.exec(lower);
  if (m) {
    const n = parseInt(m[1], 10);
    const u = m[2].toLowerCase();
    const ms = u === "d" ? n * 86400000 : u === "min" || u === "m" ? n * 60000 : n * 3600000;
    return new Date(now.getTime() - ms);
  }

  // 2) 相对偏移：过去8小时 / 8小时前 / 近3天 / 30分钟前 / 2天前
  m = /(?:过去|近)?\s*(\d+)\s*(小时|h|钟头|分钟|min|天|日|d)\s*(前|之内|内|以前)?/.exec(text);
  if (m) {
    const n = parseInt(m[1], 10);
    const unit = m[2];
    let ms;
    if (unit === "分钟" || unit === "min") ms = n * 60000;
    else if (unit === "小时" || unit === "h" || unit === "钟头") ms = n * 3600000;
    else ms = n * 86400000; // 天/日/d
    return new Date(now.getTime() - ms);
  }

  // 3) 现在
  if (/^(现在|目前|此刻|当前|now)$/i.test(lower)) return new Date(now.getTime());

  // 4) 日期词 + 可选时段/时刻
  const dw = /(今天|今日|当天|昨天|昨日|前天|大前天|明天|明日|明早|明晚|明晨|明午|今早|今晨|今午|中午|今晚|昨晚)/.exec(text);
  if (dw) {
    const w = dw[1];
    let base;
    if (w === "今天" || w === "今日" || w === "当天" || w === "今早" || w === "今晨" ||
        w === "今午" || w === "中午" || w === "今晚") {
      base = _startOfDay(now);
    } else if (w === "昨天" || w === "昨日" || w === "昨晚") {
      base = _addDays(_startOfDay(now), -1);
    } else if (w === "前天") {
      base = _addDays(_startOfDay(now), -2);
    } else if (w === "大前天") {
      base = _addDays(_startOfDay(now), -3);
    } else {
      base = _addDays(_startOfDay(now), 1); // 明天/明日/明早/明晚/明晨/明午
    }
    const hm = _parseHm(text);
    let hh = hm ? hm[0] : 0;
    let mm = hm ? hm[1] : 0;
    if (/下午|傍晚|晚上|晚间|明晚|今晚|昨晚/.test(text) && hm && hh < 12) hh += 12;
    if (/凌晨|清晨/.test(text) && hm && hh === 12) hh = 0;
    if (/中午|今午|明午/.test(text) && !hm) { hh = 12; mm = 0; }
    if (/早上|上午|今早|明早|今晨/.test(text) && !hm) { hh = 8; mm = 0; }
    if (/今晚|晚上|傍晚|昨晚/.test(text) && !hm) { hh = 20; mm = 0; } // 晚上无时刻兜底 20:00
    return _atTime(base, hh, mm);
  }

  // 5) 本周日 23:59:59（须先于「本周」判定，否则「本周日」会被「本周」子串抢先）
  if (/本周日|本周末|周日|周天/.test(text)) {
    const d = _startOfDay(now);
    const dow = (d.getDay() + 6) % 7;
    return _atTime(_addDays(d, 6 - dow), 23, 59, 59);
  }
  // 本周一 00:00 / 本周（本周一）
  if (/本周一|本周/.test(text)) {
    const d = _startOfDay(now);
    const dow = (d.getDay() + 6) % 7; // 周一=0
    return _addDays(d, -dow);
  }

  // 6) 仅 HH:MM（无日期词）→ 今天该时刻
  const hm2 = _parseHm(text);
  if (hm2) return _atTime(_startOfDay(now), hm2[0], hm2[1]);

  return null;
}

// 解析一对 [start, end]；end 缺省视为 now。返回 {start, end, start_iso, end_iso} 或 null。
function parseWindow(startText, endText, now) {
  now = now || new Date();
  const s = parseNaturalTime(startText, now);
  if (!s) return null;
  const e = endText ? parseNaturalTime(endText, now) : new Date(now.getTime());
  if (!e) return null;
  return {
    start: s,
    end: e,
    start_iso: toHAISO(s),
    end_iso: toHAISO(e),
  };
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = { parseNaturalTime, toHAISO, parseWindow, _startOfDay, _addDays, _atTime, _parseHm };
}

function _feedNode(msg, start, end) {
  // 注入机制（#107 定论，依据 api-get-history 0.80.3 源码实证，勿再改）：
  // dist/nodes/get-history/index.js 的输入声明为
  //   startDate:{messageProp:["payload.startDate"], configProp:"startDate"}
  //   endDate  :{messageProp:["payload.endDate"],   configProp:"endDate"}
  //   entityId :{messageProp:["payload.entityId"],  configProp:"entityId"}
  // 即节点原生支持经 msg.payload.* 覆盖面板配置（messageProp 优先于 configProp）。
  // 故窗口与实体一律走 msg.payload.* 注入，这是官方支持路径，无需任何节点属性改写。
  //
  // ⚠️ 已废弃路径，勿回退（#107 死结）：曾用 NR 运行时节点查找 API 反查 n_hist 实例并
  // 改写其节点属性。但 function 沙箱内该 API 不可用 → 守卫三元取 null → 其后的 fallback
  // 分支又对同一 API 裸调用 → 必然抛错（进入 fallback 的前提恰恰是该 API 不可用），
  // 子流程整体静默失败。该路径已整体删除，本文件不再留任何运行时节点查找引用。
  //
  // G1.5(#107) 修复：入站 payload 可能是数字/字符串时间戳（实测 at/start 落在 payload）。
  // 旧写法 !msg.payload 对数字/非空字符串为 truthy 不触发重置 → 后续 msg.payload.entityId
  // 给原始值赋属性被 JS 静默忽略 → entityId 注入全失 → ValidationError。
  // 改为：payload 非对象（含数字/字符串/数组/null/undefined）一律重置为空对象后再注入。
  if (!msg.payload || typeof msg.payload !== "object" || Array.isArray(msg.payload)) {
    msg.payload = {};
  }
  msg.payload.startDate = toHAISO(start);
  msg.payload.endDate = toHAISO(end);
  msg.payload.entityId = msg.entity || "";
  return msg;
}

const now = new Date();
let s = parseNaturalTime(msg.start, now);
// end 缺省（未给 / 解析不出）→ now+60s，语义=「查到现在」
let e = parseNaturalTime(msg.end, now) || new Date(now.getTime() + 60000);
// ⚠️ #118 修复，勿回退为「过去 end 一律钳到 now」：
//   旧代码 `if (e < now) e = now+60s` 的立论是「api-get-history 对过去 endDate 返回空数组」，
//   该前提【已实测证伪】——GetHistoryController 只是把 endDate 原样透传给
//   HA /api/history/period 的 end_time，过去时间正常返回数据（2026-08-04 实测：
//   昨天00:00→今天00:00 返回 11 条）。旧钳位会把用户显式指定的过去 end 偷偷改成「现在」，
//   使「昨天00:00→今天00:00」变成「昨天00:00→现在」，把今天的数据混进昨天的统计
//   （实测 mean(temperature) 24.7 被污染成 24.909）。
// 现在只钳【未来】end：未来时刻尚无历史，钳到 now 才有意义。
if (e.getTime() > now.getTime()) e = new Date(now.getTime() + 60000);
// G1 future-guard：未来 start（如凌晨跑「今日08:00」）→ 钳到 now，避免 start>end 反向窗口
// → HA 抛 ValidationError: startDate must be a valid date；并兜底交换防反向窗口。
if (s && s.getTime() > now.getTime()) s = new Date(now.getTime());
if (s && e && s.getTime() > e.getTime()) { const _t = s; s = e; e = _t; }
msg._hist_start = toHAISO(s);
msg._hist_end = toHAISO(e);
return _feedNode(msg, s, e);

// HA 取数失败（404 无历史 / 网络 / 鉴权）→ 降级为空结果数组，
// 让 compute 函数返回 found=false / occurred=false / duration=0 等结构化空答案，
// 而非让消息丢失导致下游『分支』中断。
msg._hist_error = (msg.error && (msg.error.message || String(msg.error))) || 'unknown';
msg.payload = [];
return msg;

// compute.js — 历史查询 4 类计算（在 NR function 节点内执行）。
// 输入：msg.payload 为 api-get-history 返回的状态数组（HA history REST 形状）。
// 状态条目假设形状：{ entity_id, state, attributes, last_changed, last_updated }
//   - 取值：attribute 给定 → entry.attributes[attribute]；否则 → entry.state
//   - 时间：用 last_changed（状态变化时刻）作为该条状态的有效起点
// 输出：把答案对象写回 msg.payload（供下游『提取/分支』读取）。
//
// 本文件可作 Node 模块 require（module.exports 守卫在 NR 中被跳过）。
// 能量统计（energy）走 statistics 而非 history，由 build_subflows.py 另配 REST 节点，
// 此处 computeEnergy 解析 statistics 桶（sum change 字段）。

function _valOf(entry, attribute) {
  if (attribute) {
    const a = entry.attributes || {};
    return (a[attribute] !== undefined) ? a[attribute] : entry.state;
  }
  return entry.state;
}

function _tsOf(entry) {
  const t = entry.last_changed || entry.last_updated || entry.lu || entry.lc;
  return t ? new Date(t).getTime() : NaN;
}

function _valOfAttr(entry, attribute) {
  return _valOf(entry, attribute);
}

// HA 的 /api/history/period 在某些版本会把单实体历史包成 [[...]]（外层数组只含
// 一个内层数组）。api-get-history 节点可能原样透传。若首元素仍是数组则拍平一层，
// 否则 compute* 会拿 wrapper 当 entry（_tsOf 返回 NaN → best=null → 静默 found=false）。
function _ensureFlat(arr) {
  if (Array.isArray(arr) && arr.length && Array.isArray(arr[0])) {
    return arr[0];
  }
  return arr;
}

// 1) 某时刻状态：as-of 语义 —— 取【目标时刻及之前】最后一次采样。
//
// ⚠️ #118 修复，勿回退为 Math.abs 最近邻：
//   状态是阶跃保持的（一次变化后一直有效到下次变化），所以「T 时刻的状态」= T 之前
//   最后一次变化后的值。旧实现按 |t-target| 取绝对最近，会选到 target【之后】的采样，
//   等于用未来状态回答过去问题。
//   实测反例（2026-08-04，climate.lumi_v3_db16_air_conditioner，目标 2026-08-03T23:12+08）：
//     采样 15:12:00Z='off'（目标前 6h，窗口边界态） / 15:34:31Z='cool'（目标后 22min）
//     旧实现 → 'cool'（错，那时空调还没开）；as-of → 'off'（对）。
//   HA /api/history/period 会在窗口起点合成一条「当时生效状态」，故只要 target 落在
//   窗口内，几乎总能找到 t<=target 的采样。
// 找不到前驱时（target 早于窗口起点）回退最近后继，并用 source='after_target' 显式标注，
// 让下游能区分「确证值」与「近似值」，而不是静默给出可疑答案。
function computeStateAt(msg, arr) {
  arr = _ensureFlat(arr);
  const target = new Date(msg._hist_target).getTime();
  const miss = () => ({
    found: false, entity: msg.entity, at_iso: msg._hist_target_iso,
    value: null, attribute: msg.attribute || null, nearest_ts: null, source: null
  });
  if (!arr || !arr.length) return miss();
  let asOf = null, asOfT = -Infinity;   // t <= target 中最晚的
  let after = null, afterT = Infinity;  // t >  target 中最早的
  for (const e of arr) {
    const t = _tsOf(e);
    if (isNaN(t)) continue;
    if (t <= target) {
      if (t > asOfT) { asOfT = t; asOf = e; }
    } else if (t < afterT) { afterT = t; after = e; }
  }
  const best = asOf || after;
  if (!best) return miss();
  return {
    found: true, entity: msg.entity, at_iso: msg._hist_target_iso,
    value: _valOf(best, msg.attribute), attribute: msg.attribute || null,
    unit: (best.attributes && best.attributes.unit_of_measurement) || null,
    nearest_ts: new Date(_tsOf(best)).toISOString(),
    // 'as_of'       = 目标时刻确实生效的状态（可信）
    // 'after_target'= 目标早于可用历史，返回的是其后最近采样（近似，下游可据此降级措辞）
    source: asOf ? "as_of" : "after_target"
  };
}

// 2) 区间内是否发生（状态变化 / 达到某态）
function computeOccurred(msg, arr) {
  arr = _ensureFlat(arr);
  const start = new Date(msg._hist_start).getTime();
  const end = new Date(msg._hist_end).getTime();
  const want = msg.state; // 目标态；undefined → 任意变化
  const attr = msg.attribute;
  let count = 0;
  const events = [];
  let prev = null;
  for (const e of arr) {
    const t = _tsOf(e);
    if (isNaN(t)) continue;
    if (t < start || t > end) { prev = { v: _valOfAttr(e, attr), t }; continue; }
    const v = _valOfAttr(e, attr);
    if (prev && prev.v !== v) {
      // ⚠️ #118 修复，勿回退加回 `prev.v === want`：
      //   指定 state 时只计「变成 want」的次数。旧实现把「离开 want」也计入，
      //   导致次数翻倍。实测（2026-08-03 空调 state='off'）旧版 count=4，
      //   明细为 cool→off / off→cool / cool→off / off→cool，真正「变成 off」只有 2 次。
      if (!want ? true : v === want) {
        count++;
        events.push({ ts: new Date(t).toISOString(), from: prev.v, to: v });
      }
    } else if (!prev) {
      // 窗口内第一条采样即处于目标态（HA 会在窗口起点合成当时生效状态）→ 记 1 次
      if (want && v === want) { count++; events.push({ ts: new Date(t).toISOString(), from: null, to: v }); }
    }
    prev = { v, t };
  }
  return {
    occurred: count > 0, entity: msg.entity,
    start_iso: msg._hist_start, end_iso: msg._hist_end,
    count, state: want || null,
    events,
    first_ts: events.length ? events[0].ts : null,
    last_ts: events.length ? events[events.length - 1].ts : null
  };
}

// 3) 区间内处于某态的累计时长
function computeDuration(msg, arr) {
  arr = _ensureFlat(arr);
  const start = new Date(msg._hist_start).getTime();
  const end = new Date(msg._hist_end).getTime();
  const want = msg.state;
  const attr = msg.attribute;
  let total = 0;
  let prev = null;
  for (const e of arr) {
    const t = _tsOf(e);
    if (isNaN(t)) continue;
    const v = _valOfAttr(e, attr);
    if (prev) {
      const segStart = Math.max(prev.t, start);
      const segEnd = Math.min(t, end);
      if (segEnd > segStart && prev.v === want) total += (segEnd - segStart);
    }
    prev = { v, t };
  }
  if (prev && prev.v === want) {
    const segStart = Math.max(prev.t, start);
    if (end > segStart) total += (end - segStart);
  }
  const sec = Math.floor(total / 1000);
  const h = Math.floor(sec / 3600), m = Math.floor((sec % 3600) / 60), s = sec % 60;
  const human = (h > 0 ? h + "小时" : "") + (m > 0 ? m + "分" : "") +
    (s > 0 || (h === 0 && m === 0) ? s + "秒" : "");
  return {
    total_seconds: sec, total_human: human || "0秒", entity: msg.entity,
    start_iso: msg._hist_start, end_iso: msg._hist_end, state: want,
    ratio: (end > start) ? +(total / (end - start)).toFixed(4) : 0
  };
}

// 4a) 聚合：count / mean / min / max / sum（基于 history 数组的数值属性）
function computeAggregate(msg, arr) {
  arr = _ensureFlat(arr);
  const metric = msg.metric;
  const attr = msg.attribute;
  if (metric === "count") {
    let count = 0, prev = null;
    for (const e of arr) {
      const v = _valOfAttr(e, attr);
      if (prev && prev !== v) count++;
      else if (!prev) count++;
      prev = v;
    }
    return { value: count, unit: "次", entity: msg.entity,
      start_iso: msg._hist_start, end_iso: msg._hist_end, metric, attribute: attr || null };
  }
  const nums = [];
  let unit = null;
  for (const e of arr) {
    const raw = attr ? _valOfAttr(e, attr) : e.state;
    const n = parseFloat(raw);
    if (!isNaN(n)) {
      nums.push(n);
      // 取首个可用的 unit_of_measurement（#118：旧版恒为 null，下游拿不到量纲）
      if (unit === null && e.attributes && e.attributes.unit_of_measurement) {
        unit = e.attributes.unit_of_measurement;
      }
    }
  }
  if (!nums.length) {
    return { value: null, unit: null, entity: msg.entity,
      start_iso: msg._hist_start, end_iso: msg._hist_end, metric,
      attribute: attr || null, samples: 0, error: "无数值数据" };
  }
  let value;
  if (metric === "mean") value = nums.reduce((a, b) => a + b, 0) / nums.length;
  else if (metric === "min") value = Math.min.apply(null, nums);
  else if (metric === "max") value = Math.max.apply(null, nums);
  else if (metric === "sum") value = nums.reduce((a, b) => a + b, 0);
  // ⚠️ mean 为【采样算术均值】而非时间加权均值：采样密集的时段权重更高。
  //    需要时间加权请另开 metric（当前语义保持与旧版一致，避免静默改变已有 flow 的结果）。
  return { value, unit, entity: msg.entity,
    start_iso: msg._hist_start, end_iso: msg._hist_end, metric,
    attribute: attr || null, samples: nums.length };
}

// 4b) 能量聚合：解析 statistics REST 返回的桶数组，累加每段 change（kWh）
// statistics 响应形状（HA）：{ "<statistic_id>": [ {start, end, mean, sum, change, ...}, ... ] }
function computeEnergy(msg, statObj) {
  const buckets = (statObj && typeof statObj === "object")
    ? Object.values(statObj).flat() : [];
  let kwh = 0;
  for (const b of buckets) {
    const c = (b && (b.change != null)) ? parseFloat(b.change) : NaN;
    if (!isNaN(c)) kwh += c;
  }
  return {
    value: +kwh.toFixed(3), unit: "kWh", entity: msg.entity,
    start_iso: msg._hist_start, end_iso: msg._hist_end,
    metric: "energy", attribute: msg.attribute || "energy"
  };
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = {
    computeStateAt, computeOccurred, computeDuration,
    computeAggregate, computeEnergy, _valOf, _tsOf, _valOfAttr
  };
}

const arr = msg.payload || [];
msg.payload = computeOccurred(msg, arr);
return msg;

// time_parse.js — 自然语言时间解析（Home Assistant 历史查询子流程用）
//
// 把用户表述的中文/英文混合时间，解析成本地时区的 Date（与用户说的墙上时钟一致）。
// 例：昨晚23:12 / 昨天11:00 / 前天08:30 / 今天09:15 / 现在 / 过去8小时 / 8h / 1d /
//     本周 / 本周日 / 2026-07-19T23:12 / 2026-07-19 23:12
//
// 本文件整体可作为 NR function 节点体使用：
//   - 纯函数 parseNaturalTime / toHAISO 在节点作用域内可用；
//   - 底部的 module.exports 守卫在 NR 中会被跳过（NR 不定义 module）。
// 也可被 Node 直接 require 做单元测试。

function _startOfDay(d) {
  const x = new Date(d);
  x.setHours(0, 0, 0, 0);
  return x;
}

function _addDays(d, n) {
  const x = new Date(d);
  x.setDate(x.getDate() + n);
  return x;
}

function _atTime(day, hh, mm, ss) {
  const x = new Date(day);
  x.setHours(hh, mm || 0, ss == null ? 0 : ss, 0);
  return x;
}

// 从文本中搜索 "HH:MM" / "H:MM" / "HH：MM" → [h, m]；否则 null。
// 用搜索（非 ^...$ 锚定），以便 "昨晚23:12" 这类带前缀的表述也能取出时刻。
function _parseHm(s) {
  const m = /(\d{1,2})[:：](\d{1,2})/.exec(s);
  if (!m) return null;
  return [parseInt(m[1], 10), parseInt(m[2], 10)];
}

// 把 Date 格式化为 HA history API 友好的 ISO 8601（带本地时区偏移）。
// HA 内部以 UTC 存储；传入带偏移的 ISO 可被正确换算为该墙上时刻，避免被当成 UTC 而偏移 8 小时。
function toHAISO(d) {
  const off = -d.getTimezoneOffset(); // 分钟，东半球为正
  const sign = off >= 0 ? "+" : "-";
  const abs = Math.abs(off);
  const oh = String(Math.floor(abs / 60)).padStart(2, "0");
  const om = String(abs % 60).padStart(2, "0");
  const Y = d.getFullYear();
  const M = String(d.getMonth() + 1).padStart(2, "0");
  const D = String(d.getDate()).padStart(2, "0");
  const h = String(d.getHours()).padStart(2, "0");
  const mi = String(d.getMinutes()).padStart(2, "0");
  const s = String(d.getSeconds()).padStart(2, "0");
  return `${Y}-${M}-${D}T${h}:${mi}:${s}${sign}${oh}:${om}`;
}

function parseNaturalTime(text, now) {
  if (text == null) return null;
  text = String(text).trim();
  if (!text) return null;
  now = now || new Date();
  const lower = text.toLowerCase();

  // 0) 绝对 ISO 带时刻：2026-07-19T23:12 / 2026-07-19 23:12 / 2026/07/19 23:12
  let m = /^(\d{4})[-/](\d{1,2})[-/](\d{1,2})[ T](\d{1,2})[:：](\d{1,2})/.exec(text);
  if (m) {
    return new Date(+m[1], +m[2] - 1, +m[3], +m[4], +m[5], 0, 0);
  }
  // 仅日期：2026-07-19 → 当天 00:00
  m = /^(\d{4})[-/](\d{1,2})[-/](\d{1,2})$/.exec(text);
  if (m) {
    return _atTime(new Date(+m[1], +m[2] - 1, +m[3]), 0, 0);
  }

  // 1) 紧凑相对：8h / 1d / 24h / 30min
  m = /^(\d+)\s*(h|d|min|m)$/i.exec(lower);
  if (m) {
    const n = parseInt(m[1], 10);
    const u = m[2].toLowerCase();
    const ms = u === "d" ? n * 86400000 : u === "min" || u === "m" ? n * 60000 : n * 3600000;
    return new Date(now.getTime() - ms);
  }

  // 2) 相对偏移：过去8小时 / 8小时前 / 近3天 / 30分钟前 / 2天前
  m = /(?:过去|近)?\s*(\d+)\s*(小时|h|钟头|分钟|min|天|日|d)\s*(前|之内|内|以前)?/.exec(text);
  if (m) {
    const n = parseInt(m[1], 10);
    const unit = m[2];
    let ms;
    if (unit === "分钟" || unit === "min") ms = n * 60000;
    else if (unit === "小时" || unit === "h" || unit === "钟头") ms = n * 3600000;
    else ms = n * 86400000; // 天/日/d
    return new Date(now.getTime() - ms);
  }

  // 3) 现在
  if (/^(现在|目前|此刻|当前|now)$/i.test(lower)) return new Date(now.getTime());

  // 4) 日期词 + 可选时段/时刻
  const dw = /(今天|今日|当天|昨天|昨日|前天|大前天|明天|明日|明早|明晚|明晨|明午|今早|今晨|今午|中午|今晚|昨晚)/.exec(text);
  if (dw) {
    const w = dw[1];
    let base;
    if (w === "今天" || w === "今日" || w === "当天" || w === "今早" || w === "今晨" ||
        w === "今午" || w === "中午" || w === "今晚") {
      base = _startOfDay(now);
    } else if (w === "昨天" || w === "昨日" || w === "昨晚") {
      base = _addDays(_startOfDay(now), -1);
    } else if (w === "前天") {
      base = _addDays(_startOfDay(now), -2);
    } else if (w === "大前天") {
      base = _addDays(_startOfDay(now), -3);
    } else {
      base = _addDays(_startOfDay(now), 1); // 明天/明日/明早/明晚/明晨/明午
    }
    const hm = _parseHm(text);
    let hh = hm ? hm[0] : 0;
    let mm = hm ? hm[1] : 0;
    if (/下午|傍晚|晚上|晚间|明晚|今晚|昨晚/.test(text) && hm && hh < 12) hh += 12;
    if (/凌晨|清晨/.test(text) && hm && hh === 12) hh = 0;
    if (/中午|今午|明午/.test(text) && !hm) { hh = 12; mm = 0; }
    if (/早上|上午|今早|明早|今晨/.test(text) && !hm) { hh = 8; mm = 0; }
    if (/今晚|晚上|傍晚|昨晚/.test(text) && !hm) { hh = 20; mm = 0; } // 晚上无时刻兜底 20:00
    return _atTime(base, hh, mm);
  }

  // 5) 本周日 23:59:59（须先于「本周」判定，否则「本周日」会被「本周」子串抢先）
  if (/本周日|本周末|周日|周天/.test(text)) {
    const d = _startOfDay(now);
    const dow = (d.getDay() + 6) % 7;
    return _atTime(_addDays(d, 6 - dow), 23, 59, 59);
  }
  // 本周一 00:00 / 本周（本周一）
  if (/本周一|本周/.test(text)) {
    const d = _startOfDay(now);
    const dow = (d.getDay() + 6) % 7; // 周一=0
    return _addDays(d, -dow);
  }

  // 6) 仅 HH:MM（无日期词）→ 今天该时刻
  const hm2 = _parseHm(text);
  if (hm2) return _atTime(_startOfDay(now), hm2[0], hm2[1]);

  return null;
}

// 解析一对 [start, end]；end 缺省视为 now。返回 {start, end, start_iso, end_iso} 或 null。
function parseWindow(startText, endText, now) {
  now = now || new Date();
  const s = parseNaturalTime(startText, now);
  if (!s) return null;
  const e = endText ? parseNaturalTime(endText, now) : new Date(now.getTime());
  if (!e) return null;
  return {
    start: s,
    end: e,
    start_iso: toHAISO(s),
    end_iso: toHAISO(e),
  };
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = { parseNaturalTime, toHAISO, parseWindow, _startOfDay, _addDays, _atTime, _parseHm };
}

function _feedNode(msg, start, end) {
  // 注入机制（#107 定论，依据 api-get-history 0.80.3 源码实证，勿再改）：
  // dist/nodes/get-history/index.js 的输入声明为
  //   startDate:{messageProp:["payload.startDate"], configProp:"startDate"}
  //   endDate  :{messageProp:["payload.endDate"],   configProp:"endDate"}
  //   entityId :{messageProp:["payload.entityId"],  configProp:"entityId"}
  // 即节点原生支持经 msg.payload.* 覆盖面板配置（messageProp 优先于 configProp）。
  // 故窗口与实体一律走 msg.payload.* 注入，这是官方支持路径，无需任何节点属性改写。
  //
  // ⚠️ 已废弃路径，勿回退（#107 死结）：曾用 NR 运行时节点查找 API 反查 n_hist 实例并
  // 改写其节点属性。但 function 沙箱内该 API 不可用 → 守卫三元取 null → 其后的 fallback
  // 分支又对同一 API 裸调用 → 必然抛错（进入 fallback 的前提恰恰是该 API 不可用），
  // 子流程整体静默失败。该路径已整体删除，本文件不再留任何运行时节点查找引用。
  //
  // G1.5(#107) 修复：入站 payload 可能是数字/字符串时间戳（实测 at/start 落在 payload）。
  // 旧写法 !msg.payload 对数字/非空字符串为 truthy 不触发重置 → 后续 msg.payload.entityId
  // 给原始值赋属性被 JS 静默忽略 → entityId 注入全失 → ValidationError。
  // 改为：payload 非对象（含数字/字符串/数组/null/undefined）一律重置为空对象后再注入。
  if (!msg.payload || typeof msg.payload !== "object" || Array.isArray(msg.payload)) {
    msg.payload = {};
  }
  msg.payload.startDate = toHAISO(start);
  msg.payload.endDate = toHAISO(end);
  msg.payload.entityId = msg.entity || "";
  return msg;
}

// 某时刻状态：回看 6h 取最近邻采样（覆盖『T 之前最后一次状态』场景）
// ⚠️ api-get-history 节点要求 endDate >= now，否则返回空数组；故 end 用 now（而非 target+1min）。
const now = new Date();
let target = parseNaturalTime(msg.at, now) || new Date(now.getTime());
// G1 future-guard：at 在未来（如凌晨跑「今日08:00」）→ 钳到 now，语义等价于「此刻状态」，
// 避免 start>end 反向窗口 → HA 抛 ValidationError: startDate must be a valid date。
if (target.getTime() > now.getTime()) target = new Date(now.getTime());
const start = new Date(target.getTime() - 6 * 3600 * 1000);
const end = new Date(now.getTime() + 60000);
msg._hist_start = toHAISO(start);
msg._hist_end = toHAISO(end);
msg._hist_target = toHAISO(target);
msg._hist_target_iso = toHAISO(target);
return _feedNode(msg, start, end);

// HA 取数失败（404 无历史 / 网络 / 鉴权）→ 降级为空结果数组，
// 让 compute 函数返回 found=false / occurred=false / duration=0 等结构化空答案，
// 而非让消息丢失导致下游『分支』中断。
msg._hist_error = (msg.error && (msg.error.message || String(msg.error))) || 'unknown';
msg.payload = [];
return msg;

// compute.js — 历史查询 4 类计算（在 NR function 节点内执行）。
// 输入：msg.payload 为 api-get-history 返回的状态数组（HA history REST 形状）。
// 状态条目假设形状：{ entity_id, state, attributes, last_changed, last_updated }
//   - 取值：attribute 给定 → entry.attributes[attribute]；否则 → entry.state
//   - 时间：用 last_changed（状态变化时刻）作为该条状态的有效起点
// 输出：把答案对象写回 msg.payload（供下游『提取/分支』读取）。
//
// 本文件可作 Node 模块 require（module.exports 守卫在 NR 中被跳过）。
// 能量统计（energy）走 statistics 而非 history，由 build_subflows.py 另配 REST 节点，
// 此处 computeEnergy 解析 statistics 桶（sum change 字段）。

function _valOf(entry, attribute) {
  if (attribute) {
    const a = entry.attributes || {};
    return (a[attribute] !== undefined) ? a[attribute] : entry.state;
  }
  return entry.state;
}

function _tsOf(entry) {
  const t = entry.last_changed || entry.last_updated || entry.lu || entry.lc;
  return t ? new Date(t).getTime() : NaN;
}

function _valOfAttr(entry, attribute) {
  return _valOf(entry, attribute);
}

// HA 的 /api/history/period 在某些版本会把单实体历史包成 [[...]]（外层数组只含
// 一个内层数组）。api-get-history 节点可能原样透传。若首元素仍是数组则拍平一层，
// 否则 compute* 会拿 wrapper 当 entry（_tsOf 返回 NaN → best=null → 静默 found=false）。
function _ensureFlat(arr) {
  if (Array.isArray(arr) && arr.length && Array.isArray(arr[0])) {
    return arr[0];
  }
  return arr;
}

// 1) 某时刻状态：as-of 语义 —— 取【目标时刻及之前】最后一次采样。
//
// ⚠️ #118 修复，勿回退为 Math.abs 最近邻：
//   状态是阶跃保持的（一次变化后一直有效到下次变化），所以「T 时刻的状态」= T 之前
//   最后一次变化后的值。旧实现按 |t-target| 取绝对最近，会选到 target【之后】的采样，
//   等于用未来状态回答过去问题。
//   实测反例（2026-08-04，climate.lumi_v3_db16_air_conditioner，目标 2026-08-03T23:12+08）：
//     采样 15:12:00Z='off'（目标前 6h，窗口边界态） / 15:34:31Z='cool'（目标后 22min）
//     旧实现 → 'cool'（错，那时空调还没开）；as-of → 'off'（对）。
//   HA /api/history/period 会在窗口起点合成一条「当时生效状态」，故只要 target 落在
//   窗口内，几乎总能找到 t<=target 的采样。
// 找不到前驱时（target 早于窗口起点）回退最近后继，并用 source='after_target' 显式标注，
// 让下游能区分「确证值」与「近似值」，而不是静默给出可疑答案。
function computeStateAt(msg, arr) {
  arr = _ensureFlat(arr);
  const target = new Date(msg._hist_target).getTime();
  const miss = () => ({
    found: false, entity: msg.entity, at_iso: msg._hist_target_iso,
    value: null, attribute: msg.attribute || null, nearest_ts: null, source: null
  });
  if (!arr || !arr.length) return miss();
  let asOf = null, asOfT = -Infinity;   // t <= target 中最晚的
  let after = null, afterT = Infinity;  // t >  target 中最早的
  for (const e of arr) {
    const t = _tsOf(e);
    if (isNaN(t)) continue;
    if (t <= target) {
      if (t > asOfT) { asOfT = t; asOf = e; }
    } else if (t < afterT) { afterT = t; after = e; }
  }
  const best = asOf || after;
  if (!best) return miss();
  return {
    found: true, entity: msg.entity, at_iso: msg._hist_target_iso,
    value: _valOf(best, msg.attribute), attribute: msg.attribute || null,
    unit: (best.attributes && best.attributes.unit_of_measurement) || null,
    nearest_ts: new Date(_tsOf(best)).toISOString(),
    // 'as_of'       = 目标时刻确实生效的状态（可信）
    // 'after_target'= 目标早于可用历史，返回的是其后最近采样（近似，下游可据此降级措辞）
    source: asOf ? "as_of" : "after_target"
  };
}

// 2) 区间内是否发生（状态变化 / 达到某态）
function computeOccurred(msg, arr) {
  arr = _ensureFlat(arr);
  const start = new Date(msg._hist_start).getTime();
  const end = new Date(msg._hist_end).getTime();
  const want = msg.state; // 目标态；undefined → 任意变化
  const attr = msg.attribute;
  let count = 0;
  const events = [];
  let prev = null;
  for (const e of arr) {
    const t = _tsOf(e);
    if (isNaN(t)) continue;
    if (t < start || t > end) { prev = { v: _valOfAttr(e, attr), t }; continue; }
    const v = _valOfAttr(e, attr);
    if (prev && prev.v !== v) {
      // ⚠️ #118 修复，勿回退加回 `prev.v === want`：
      //   指定 state 时只计「变成 want」的次数。旧实现把「离开 want」也计入，
      //   导致次数翻倍。实测（2026-08-03 空调 state='off'）旧版 count=4，
      //   明细为 cool→off / off→cool / cool→off / off→cool，真正「变成 off」只有 2 次。
      if (!want ? true : v === want) {
        count++;
        events.push({ ts: new Date(t).toISOString(), from: prev.v, to: v });
      }
    } else if (!prev) {
      // 窗口内第一条采样即处于目标态（HA 会在窗口起点合成当时生效状态）→ 记 1 次
      if (want && v === want) { count++; events.push({ ts: new Date(t).toISOString(), from: null, to: v }); }
    }
    prev = { v, t };
  }
  return {
    occurred: count > 0, entity: msg.entity,
    start_iso: msg._hist_start, end_iso: msg._hist_end,
    count, state: want || null,
    events,
    first_ts: events.length ? events[0].ts : null,
    last_ts: events.length ? events[events.length - 1].ts : null
  };
}

// 3) 区间内处于某态的累计时长
function computeDuration(msg, arr) {
  arr = _ensureFlat(arr);
  const start = new Date(msg._hist_start).getTime();
  const end = new Date(msg._hist_end).getTime();
  const want = msg.state;
  const attr = msg.attribute;
  let total = 0;
  let prev = null;
  for (const e of arr) {
    const t = _tsOf(e);
    if (isNaN(t)) continue;
    const v = _valOfAttr(e, attr);
    if (prev) {
      const segStart = Math.max(prev.t, start);
      const segEnd = Math.min(t, end);
      if (segEnd > segStart && prev.v === want) total += (segEnd - segStart);
    }
    prev = { v, t };
  }
  if (prev && prev.v === want) {
    const segStart = Math.max(prev.t, start);
    if (end > segStart) total += (end - segStart);
  }
  const sec = Math.floor(total / 1000);
  const h = Math.floor(sec / 3600), m = Math.floor((sec % 3600) / 60), s = sec % 60;
  const human = (h > 0 ? h + "小时" : "") + (m > 0 ? m + "分" : "") +
    (s > 0 || (h === 0 && m === 0) ? s + "秒" : "");
  return {
    total_seconds: sec, total_human: human || "0秒", entity: msg.entity,
    start_iso: msg._hist_start, end_iso: msg._hist_end, state: want,
    ratio: (end > start) ? +(total / (end - start)).toFixed(4) : 0
  };
}

// 4a) 聚合：count / mean / min / max / sum（基于 history 数组的数值属性）
function computeAggregate(msg, arr) {
  arr = _ensureFlat(arr);
  const metric = msg.metric;
  const attr = msg.attribute;
  if (metric === "count") {
    let count = 0, prev = null;
    for (const e of arr) {
      const v = _valOfAttr(e, attr);
      if (prev && prev !== v) count++;
      else if (!prev) count++;
      prev = v;
    }
    return { value: count, unit: "次", entity: msg.entity,
      start_iso: msg._hist_start, end_iso: msg._hist_end, metric, attribute: attr || null };
  }
  const nums = [];
  let unit = null;
  for (const e of arr) {
    const raw = attr ? _valOfAttr(e, attr) : e.state;
    const n = parseFloat(raw);
    if (!isNaN(n)) {
      nums.push(n);
      // 取首个可用的 unit_of_measurement（#118：旧版恒为 null，下游拿不到量纲）
      if (unit === null && e.attributes && e.attributes.unit_of_measurement) {
        unit = e.attributes.unit_of_measurement;
      }
    }
  }
  if (!nums.length) {
    return { value: null, unit: null, entity: msg.entity,
      start_iso: msg._hist_start, end_iso: msg._hist_end, metric,
      attribute: attr || null, samples: 0, error: "无数值数据" };
  }
  let value;
  if (metric === "mean") value = nums.reduce((a, b) => a + b, 0) / nums.length;
  else if (metric === "min") value = Math.min.apply(null, nums);
  else if (metric === "max") value = Math.max.apply(null, nums);
  else if (metric === "sum") value = nums.reduce((a, b) => a + b, 0);
  // ⚠️ mean 为【采样算术均值】而非时间加权均值：采样密集的时段权重更高。
  //    需要时间加权请另开 metric（当前语义保持与旧版一致，避免静默改变已有 flow 的结果）。
  return { value, unit, entity: msg.entity,
    start_iso: msg._hist_start, end_iso: msg._hist_end, metric,
    attribute: attr || null, samples: nums.length };
}

// 4b) 能量聚合：解析 statistics REST 返回的桶数组，累加每段 change（kWh）
// statistics 响应形状（HA）：{ "<statistic_id>": [ {start, end, mean, sum, change, ...}, ... ] }
function computeEnergy(msg, statObj) {
  const buckets = (statObj && typeof statObj === "object")
    ? Object.values(statObj).flat() : [];
  let kwh = 0;
  for (const b of buckets) {
    const c = (b && (b.change != null)) ? parseFloat(b.change) : NaN;
    if (!isNaN(c)) kwh += c;
  }
  return {
    value: +kwh.toFixed(3), unit: "kWh", entity: msg.entity,
    start_iso: msg._hist_start, end_iso: msg._hist_end,
    metric: "energy", attribute: msg.attribute || "energy"
  };
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = {
    computeStateAt, computeOccurred, computeDuration,
    computeAggregate, computeEnergy, _valOf, _tsOf, _valOfAttr
  };
}

