    return dotCount >= 3;
}

// ============ 主标题提取函数（@ 优先 + 季集年份先清）============
function extractMainTitle(title) {
    let result = title;

    // 1. 【核心】按 @ 分割
    if (result.includes('@')) {
        const atParts = result.split('@');
        const chinesePart = atParts.find(p => /[\u4e00-\u9fa5]/.test(p));
        if (chinesePart) {
            result = chinesePart.trim();
        } else {
            result = atParts[0].trim();
        }
    }

    // 2. 按 | / 分割
    const sepParts = result.split(/[|｜\/]/);
    if (sepParts.length > 1) {
        result = sepParts[0].trim();
    }

    // 3. 移除方括号内容
    result = result.replace(/【[^】]+】/g, '').trim();
    result = result.replace(/\[[^\]]+\]/g, '').trim();
    result = result.replace(/\(.*?\)/g, '').trim();

    // 4. 移除年份（必须在点分割前）
    result = result.replace(/\b(19|20)\d{2}\b/g, '').trim();

    // 5. 移除季集信息（必须在点分割前）
    result = result.replace(/\b(第\d+季|第\d+集|全\d+集|S\d+|E\d+|EP\d+|季\d+|集\d+)\b/gi, '').trim();

    // 6. 移除常见标签词
    const tagWords = [
        '中字', '中配', '国配', '双语', '字幕', '原盘', '压制', 'REMUX',
        'BluRay', 'WEB-DL', 'UHD', '4K', 'HDR', 'DoVi', 'DV', '次世代',
        'DIY', '官译', '内封', '简体', '繁体', '粤语', '国语',
        '1080p', '2160p', '720p', '4K', '8K', '2K',
        'NF', 'AMZN', 'iTunes', 'DSNP', 'HMAX', 'ATVP', 'PMTP', 'STAN'
    ];
    tagWords.forEach(word => {
        const regex = new RegExp('\\b' + word.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b', 'gi');
        result = result.replace(regex, '').trim();
    });

    // 7. 移除"港劇:"等前缀
    result = result.replace(/^(港[剧劇]|综艺|剧集|电视剧|动漫|电影)\s*[：:]\s*/i, '').trim();

    // 8. 按 . - _ 分割取首段（如果原名不是长串英文文件名才这样做）
    if (!isRawEnglishLongName(title)) {
        const dotParts = result.split(/[.\-_]/).map(s => s.trim()).filter(s => s);
        if (dotParts.length > 1) {
            result = dotParts[0];
        }
    }

    // 9. 移除英文/数字开头（保留中文起始）
    const chineseStart = result.search(/[\u4e00-\u9fa5]/);
    if (chineseStart > 0) {
        result = result.substring(chineseStart);
    }

    // 10. 末尾清理
    result = result.replace(/[：:、，,.。·\-\s]+$/, '').trim();
    result = result.replace(/\s{2,}/g, ' ').trim();

    return result || "未命名资源";
}

