// 【TTS权限判断 + 启动过滤】全链路空值防护 + 兼容持久化 store + 启动静默期
const event = msg?.data?.event;
if (!event?.new_state || !event?.old_state) {
    node.warn('【权限判断】无效状态事件，跳过');
    return null;
}

const entityId = event.new_state.entity_id || '';
const name = event.new_state.attributes?.friendly_name || '';
const state = msg?.payload || '';
const oldState = event.old_state?.state || '';

// ====================== 修复点1：过滤HA/Node-RED启动时的批量同步 ======================
// 如果旧状态是 unknown / unavailable / 空，说明是启动同步，不是用户操作，跳过
if (oldState === 'unknown' || oldState === 'unavailable' || oldState === '') {
    node.warn('【启动过滤】跳过启动同步: ' + name);
    return null;
}

// ====================== 修复点2：Node-RED启动静默期（15秒） ======================
const now = Date.now();
const startupTime = global.get('NR_STARTUP_TIME') || 0;

// 第一次运行时记录启动时间
if (startupTime === 0) {
    global.set('NR_STARTUP_TIME', now);
    node.warn('【启动过滤】记录启动时间，进入15秒静默期');
    return null;
}

// 启动后15秒内的状态变化都忽略（防止Node-RED重启时批量触发）
const SILENT_PERIOD = 15 * 1000; // 15秒
if (now - startupTime < SILENT_PERIOD) {
    node.warn('【启动过滤】静默期内跳过: ' + name);
    return null;
}

// ====================== 原有的 houseMode 权限判断 ======================
const houseMode = global.get('houseMode', 'store') || null;

// houseMode未初始化降级策略
if (houseMode === null) {
    const allowlist = ['主','厅','卧','书','客'];
    const isAllow = allowlist.some(k => name.includes(k));
    return isAllow ? msg : null;
}

if (houseMode.tts_allow !== true) {
    return null;
}

return msg;

// 【生成播报文案】全链路空值防护 + 随机文案变化
const event = msg?.data?.event;
if (!event?.new_state) {
    node.warn('【生成播报】无效状态，跳过');
    return null;
}

const entity_id = event.new_state.entity_id || '';
const fullName = event.new_state.attributes?.friendly_name || '';
const state = msg?.payload || '';
const parts = (fullName || '').trim().split(/\s+/).filter(Boolean);

// 名称清洗
let clean_name;
if (entity_id.startsWith('switch.lumi_cn')) {
    clean_name = parts[1] || parts[0] || '设备';
} else {
    clean_name = parts[0] || '设备';
}

// 随机选一种播报文案，避免太单调
const onTexts = [
    clean_name + '已开启',
    clean_name + '打开了',
    '好的，' + clean_name + '开了'
];
const offTexts = [
    clean_name + '已关闭',
    clean_name + '关掉了',
    '好的，' + clean_name + '关了'
];

const texts = state === 'on' ? onTexts : offTexts;
const text = texts[Math.floor(Math.random() * texts.length)];

const vol = 30; // 普通开关默认小声

node.warn(`【生成播报】"${text}" volume=${vol} device=${clean_name}`);
return {
    text,
    volume: vol,
    device: entity_id,
    _state: state,
    payload: { text, volume: vol }
};

// 【TTS队列管理 v3】三通道路由 + 优先级队列 + 过载保护 + 夜间静默开关
// output[0]: 过载通知 → 直接播报  output[1]: 指令通道  output[2]: 标准TTS
// 【修改】夜间静默时间窗口改由 time-range-switch 节点控制（23:00-06:50 静默）
// 要修改时间窗口：在 NR UI 双击「TTS播报时间过滤(06:50-23:00)」节点

let raw = null;

if (msg.payload && typeof msg.payload === 'object') {
    raw = msg.payload;
} else if (typeof msg.payload === 'string') {
    raw = { text: msg.payload };
} else {
    node.warn('[TTS] 非法格式, type=' + typeof msg.payload);
    return null;
}

if (raw.aiMode === 1) {
    const aiText = (raw.text || '').trim();
    if (!aiText) { node.warn('[TTS] aiMode=1 但 text 为空'); return null; }
    node.warn('[TTS路由] AI大模型TTS (aiMode): ' + aiText.substring(0, 30));
    const ins = JSON.stringify([aiText, 1]);
    return [null, { payload: { message: ins, room: raw.room || "default" } }, null];
}

if (raw.message && !raw.text) {
    let m = String(raw.message);
    const cmdMatch = m.match(/^\[\s*["'](.+?)["']\s*,\s*(\d+)\s*\]$/);
    if (cmdMatch) {
        const cmdText = cmdMatch[1];
        const cmdFlag = parseInt(cmdMatch[2]);
        if (cmdFlag === 0) {
            node.warn('[TTS路由] 静默指令: ' + cmdText.substring(0, 30));
        } else {
            node.warn('[TTS路由] AI大模型TTS: ' + cmdText.substring(0, 30));
        }
        return [null, { payload: { message: m, room: raw.room || "default" } }, null];
    }
}

if (!raw.text && raw.message) {
    let m = String(raw.message);
    const match = m.match(/\[\s*["'](.+?)["']\s*,\s*\d+\s*\]/);
    if (match) {
        raw.text = match[1];
        node.warn('[TTS兼容] 指令格式→text: ' + raw.text.substring(0, 20));
    } else {
        raw.text = m.replace(/^["']+|["']+$/g, '').trim();
        node.warn('[TTS兼容] message→text: ' + raw.text.substring(0, 20));
    }
    delete raw.message;
}

const text = (raw.text || '').trim();
if (!text) { node.warn('[TTS] text为空'); return null; }

const priority = typeof raw.priority === 'number' ? raw.priority : 3;
const device   = raw.device || msg.device || '';
const state    = raw.state   || '';
const room     = raw.room    || 'default';
const aiMode   = raw.aiMode  || 0;
const maxChars = raw.maxChars || 100;
const ts       = raw.ts      || Date.now();
const ttl      = raw.ttl     || 300000;

const levelVol = priority === 1 ? 80 : priority === 2 ? 60 : priority <= 5 ? 30 : 30;
const volume = typeof raw.volume === 'number' ? Math.max(0, Math.min(100, raw.volume)) : levelVol;

const now = Date.now();

if (priority === 1) {
    node.warn('[TTS告警] P1强制: ' + text.substring(0, 30));
    global.set('TTS_COOLDOWN_ACTIVE', false);
    global.set('TTS_RECENT_TRIGGERS', []);
    let q = global.get('TTS_Q') || [];
    if (!Array.isArray(q)) q = [];
    q.unshift({ device, state, text, volume, room, ts: now, priority, aiMode, maxChars });
    global.set('TTS_Q', q);
    global.set('TTS_LOCK', false);
    return [null, null, { payload: 'process' }];
}

const ttsRecent = global.get('TTS_RECENT_TRIGGERS') || [];
const BURST_LIMIT = 7, BURST_WINDOW = 7000, COOLDOWN = 25000;
const recent = ttsRecent.filter(t => now - t < BURST_WINDOW);
recent.push(now);
global.set('TTS_RECENT_TRIGGERS', recent);

if (global.get('TTS_COOLDOWN_ACTIVE')) {
    node.warn('[TTS熔断] 冷却中: ' + text.substring(0, 18));
    return null;
}
if (recent.length >= BURST_LIMIT) {
    global.set('TTS_COOLDOWN_ACTIVE', true);
    node.warn('[TTS熔断] 频率过高 → 静音25秒');
    setTimeout(() => { global.set('TTS_COOLDOWN_ACTIVE', false); global.set('TTS_RECENT_TRIGGERS', []); }, COOLDOWN);
    return null;
}

