    node.warn('[TTS] 过期丢弃(' + Math.round((now-ts)/1000) + 's): ' + text.substring(0, 20));
    return null;
}

let q = global.get('TTS_Q') || [];
if (!Array.isArray(q)) q = [];

const overloadUntil = global.get('TTS_OVERLOAD_UNTIL') || 0;
