    node.warn('[TTS] 过载暂停中，剩余' + Math.round((overloadUntil-now)/1000) + 's');
    return null;
}

if (q.length >= 20) {
    const reason = 'TTS队列积压' + q.length + '条，暂停播报10分钟';
    node.warn('[TTS过载] ' + reason);
    const overloadMsg = { payload: { text: reason, device: 'system_overload', room: '客厅', priority: 1, volume: 50, ts: now, aiMode: 0 } };
    global.set('TTS_OVERLOAD_UNTIL', now + 600000);
    global.set('TTS_Q', []);
    global.set('TTS_LOCK', false);
    return [overloadMsg, null, null];
}

// 【修改】夜间静默：time-range-switch 节点已处理 23:00-06:50 硬窗口
// 此处仅检查手动开关（TTS_NIGHT_MUTE_DISABLED）
