  text = "客厅有 " + (known.length + strangerN) + " 位访客：" + known.join("、") + "，另有 " + strangerN + " 位陌生人";
} else if (known.length) {
  text = "客厅有 " + known.length + " 位熟客：" + known.join("、");
} else {
  text = "客厅有 " + strangerN + " 位陌生人";
}
node.status({ fill: "blue", shape: "dot", text: text.slice(0, 20) });
msg.payload = { text: text, room: "客厅", device: "face_multi", priority: 3 };
return msg;
